  peticion = { model: MODELO, max_tokens: 4000, system: SISTEMA, tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 4 }], messages: [{ role: 'user', content: prompt }] };
}
sd.trab[clave] = Date.now();
return [{ json: { listo: false, accion, clave, titulo, fecha, urls, peticion, hoy } }];

const CINES = [
  { id: 'cc', nombre: 'Cine Colombia', host: 'cinecolombia.com', base: 'https://www.cinecolombia.com', urls: ['https://www.cinecolombia.com/cali/cartelera', 'https://www.cinecolombia.com/cali/peliculas', 'https://www.cinecolombia.com/cali', 'https://www.cinecolombia.com/'] },
