      if (!e.cines.includes(c.id)) e.cines.push(c.id);
      const u = absoluta(p.url, c.base); if (u && !e.urls[c.id]) e.urls[c.id] = u;
      const po = absoluta(p.poster, c.base); if (po && !e.poster) e.poster = po;
      if (titulo.length < e.titulo.length) e.titulo = titulo;
    });
  });
  const pelis = Object.values(mapa).sort((a, b) => b.cines.length - a.cines.length || a.titulo.localeCompare(b.titulo)).slice(0, 40);
  const diag = sd.diag || [];
  const porCine = CINES.map(c => ({ id: c.id, cine: c.nombre, peliculas: pelis.filter(p => p.cines.includes(c.id)).length, leida: !!(diag.find(d => d.id === c.id) || {}).leida, http: (diag.find(d => d.id === c.id) || {}).http || 0, error: (diag.find(d => d.id === c.id) || {}).error || '' }));
  if (!pelis.length) return falla('No pude leer ninguna película. ' + porCine.map(x => x.cine + ': ' + (x.leida ? 'leída pero sin películas' : 'no abrió (HTTP ' + x.http + (x.error ? ', ' + x.error : '') + ')')).join(' · '));
  respuesta = { ok: true, peliculas: pelis.map(p => ({ id: p.clave, clave: p.clave, titulo: p.titulo, poster: p.poster, cines: p.cines, urls: p.urls })), porCine, actualizado: new Date().toISOString() };
} else if (v.accion === 'horarios') {
  const diagH = sd.diagH || [];
