    const cx = (Array.isArray(out.cines) ? out.cines : []).find(x => x.id === c.id) || {};
    const sedes = (Array.isArray(cx.sedes) ? cx.sedes : []).slice(0, 8).map(s => ({ sede: txt(s.sede, 50), horarios: (Array.isArray(s.horarios) ? s.horarios : []).filter(h => /^\d{1,2}:\d{2}$/.test(String(h.hora || ''))).slice(0, 14).map(h => ({ hora: String(h.hora).padStart(5, '0'), formato: txt(h.formato, 12), idioma: txt(h.idioma, 14) })) })).filter(s => s.sede && s.horarios.length);
    const url = (v.urls && v.urls[c.id]) || null;
    const d = diagH.find(x => x.id === c.id);
    const estado = !url ? 'no_esta' : sedes.length ? 'ok' : (d && !d.leida) ? 'no_leida' : 'sin_horarios';
    return { id: c.id, cine: c.nombre, url, estado, sedes, nota: txt(cx.nota, 140) };
