    datos[k] = { generos: (Array.isArray(p.generos) ? p.generos : []).slice(0, 3).map(g => txt(g, 24)), duracion: Number(p.duracion) > 0 ? Math.round(Number(p.duracion)) : null, clasificacion: txt(p.clasificacion, 12) || null, sinopsis: txt(p.sinopsis, 220), score: num(p.score), fuente: txt(p.fuente, 30), encaja: ['si', 'tal vez', 'no'].includes(p.encaja) ? p.encaja : 'tal vez', porque: txt(p.porque, 140) };
  });
  respuesta = { ok: true, datos, actualizado: new Date().toISOString() };
} else {
  const sc = (o) => ({ score: num(o && o.score), fuente: txt(o && o.fuente, 30) });
  respuesta = { ok: true, titulo: v.titulo, veredicto: ['vale', 'esperar', 'no'].includes(out.veredicto) ? out.veredicto : 'esperar', titular: txt(out.titular, 120), resumen: txt(out.resumen, 320),
    razones: (Array.isArray(out.razones) ? out.razones : []).slice(0, 3).map(x => txt(x, 140)).filter(Boolean), critica: sc(out.critica), publico: sc(out.publico),
    buzz: ['alto', 'medio', 'bajo'].includes(out.buzz) ? out.buzz : 'medio', superoExpectativas: !!out.superoExpectativas, actualizado: new Date().toISOString() };
}
sd.cache[v.clave] = { t: Date.now(), v: respuesta };
const ks = Object.keys(sd.cache);
if (ks.length > 80) ks.sort((a, b) => sd.cache[a].t - sd.cache[b].t).slice(0, ks.length - 80).forEach(k => delete sd.cache[k]);
return [{ json: { respuesta } }];

const CINES = [
  { id: 'cc', nombre: 'Cine Colombia', host: 'cinecolombia.com', base: 'https://www.cinecolombia.com', urls: ['https://www.cinecolombia.com/cali/cartelera', 'https://www.cinecolombia.com/cali/peliculas', 'https://www.cinecolombia.com/cali', 'https://www.cinecolombia.com/'] },
