// HTML → texto corto: conserva títulos, enlaces [A url], imágenes [IMG url] y los datos JSON que traiga la página
const compacto = (html, base) => {
  const abs = (u) => { try { return new URL(String(u).trim().split(/\s+/)[0], base).href; } catch (e) { return ''; } };
  let datos = '';
  const nd = html.match(/<script[^>]*id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/i); if (nd) datos += '\nDATOS_NEXT: ' + nd[1].slice(0, 14000);
  (html.match(/<script[^>]*application\/ld\+json[^>]*>[\s\S]*?<\/script>/gi) || []).slice(0, 3).forEach(s => { datos += '\nDATOS_LD: ' + s.replace(/<[^>]+>/g, '').slice(0, 4000); });
