  t = t.replace(/<img\b[^>]*>/gi, (m) => { const s = (m.match(/\b(?:data-src|data-lazy-src|data-original|src)=["']([^"']+)["']/i) || m.match(/\bsrcset=["']([^"']+)["']/i) || [])[1]; const alt = (m.match(/\balt=["']([^"']*)["']/i) || [])[1] || ''; return s && !/^data:/.test(s) ? ' [IMG ' + abs(s) + (alt ? ' alt=' + alt.slice(0, 60) : '') + '] ' : ' '; });
