};
const traer = async (urls) => {
  let status = 0, err = '';
  for (const u of urls) {
    try {
      const r = await http({ method: 'GET', url: u, headers: H, timeout: 20000, returnFullResponse: true, ignoreHttpStatusErrors: true, json: false });
