const leidos = await Promise.all(ids.map(async (c) => { const r = await traer([v.urls[c.id]]); return { c, r, texto: r.html ? compacto(r.html, r.url) : '' }; }));
sd.diagH = leidos.map(x => ({ id: x.c.id, leida: !!x.r.html, http: x.r.status, error: x.r.err }));
const secciones = leidos.filter(x => x.texto).map(x => '=== ' + x.c.id + ' · ' + x.c.nombre + ' ===\n' + x.texto).join('\n\n');
const prompt = secciones
